    if (DoesPendingTurnRequestValidationContextMatchAuthorityPayload(payload, repairContext))
        return true;

    var turnContext = LoadPendingTurnRequestValidationContextSync(
        "input/turn_request.json",
        writeLease);
    if (DoesPendingTurnRequestValidationContextMatchAuthorityPayload(payload, turnContext))
        return true;

    var completionContext = LoadPendingTurnRequestValidationContextSync(
        "ready/turn_complete.json",
        writeLease);
    return DoesPendingTurnRequestValidationContextMatchAuthorityPayload(payload, completionContext);
}

private static bool DoesPendingTurnRequestValidationContextMatchManifest(
    ValidationPendingTurnSnapshotManifest manifest,
    PendingTurnRequestValidationContext? context)
{
    if (context == null)
        return false;

    if (manifest.TurnNumber != context.TurnNumber)
        return false;

    if (!DoesPendingTurnContextIdMatch(manifest.SessionId, context.SessionId))
        return false;

    if (!DoesPendingTurnContextIdMatch(manifest.RequestId, context.RequestId))
        return false;

    return true;
}

